/// Byte offset of `prop_count` in a START_NPU Cmd BO from
/// [`build_ert_start_npu_cmd_bo_with_kernel_args`] / `_ex`.
///
/// Layout: packed header **4** B + CU mask (4) + buffer u64 (8) + buffer_size (4)
/// → prop_count at **20**. (Not 28 — that is n_bos hi after kernel args begin.)
pub const START_NPU_PROP_COUNT_BYTE_OFF: usize = 20;

/// Read START_NPU `prop_count` from a packed Cmd BO (same offset as direct unit tests).
#[must_use]
pub fn prop_count_from_start_npu_cmd_bo(bo: &[u8]) -> Option<u32> {
    let off = START_NPU_PROP_COUNT_BYTE_OFF;
    bo.get(off..off + 4)
        .map(|b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]))
}

/// Default lab QoS gops when env unset (makes driver `is_valid_qos_dpm_params` happy).
pub const LAB_DEFAULT_QOS_GOPS: u32 = 100;
/// Default lab QoS fps when env unset.
pub const LAB_DEFAULT_QOS_FPS: u32 = 30;

/// What value goes into START_NPU `instruction_buffer_size` / `inst_size`.
///
/// Device BO is still zero-padded to page (`bo_alloc`, often 4096). Userspace
/// may advertise **content** size (ctrltext/txn_size, e.g. 1688) or full **bo**
/// size (page, e.g. 4096).
///
/// Env: `XDNA2_LAB_INSTR_SIZE_MODE=content|bo` (default **content**).
///
/// **Content resolve:** when both `content_len` and `bo_alloc` are non-zero,
/// [`resolve_start_npu_inst_size`] returns `min(content_len, bo_alloc)` so
/// START_NPU never advertises DMA longer than the written BO (see
/// [`instr_size_content_clamped`]). Zero content falls back to `bo_alloc`.
///
/// **Live residual (CLOSED env HITL):** both content=1688 and historical bo=4096
/// still yield FW `APP_LOAD_PDI_FAIL` (`0x3000003`) with aiebu ELF+rela×12 on
/// 2026-07-16. Size mode is locked offline for contract honesty only — **not**
/// a silicon Pass knob and **not** C-ready.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum LabInstrSizeMode {
    /// START_NPU size = content length, **clamped to `bo_alloc`** when both set
    /// (default; live content trial CLOSED still APP_LOAD).
    #[default]
    Content,
    /// START_NPU size = BO allocation (XRT `bo.size()` page-aligned parity).
    Bo,
}

impl LabInstrSizeMode {
    /// Stable token for detail strings.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Content => "content",
            Self::Bo => "bo",
        }
    }
}

/// Fail-closed parse of `XDNA2_LAB_INSTR_SIZE_MODE`.
///
/// Unset / empty → [`LabInstrSizeMode::Content`]. Known: `content`, `bo`
/// (aliases `alloc`/`page` → bo). Unknown tokens → `Err` (no silent default).
///
/// # Errors
///
/// Unrecognized non-empty token.
pub fn try_lab_instr_size_mode_from_str(raw: Option<&str>) -> Result<LabInstrSizeMode, String> {
    match raw.map(str::trim).filter(|s| !s.is_empty()) {
        None => Ok(LabInstrSizeMode::Content),
        Some(s) if s.eq_ignore_ascii_case("content") => Ok(LabInstrSizeMode::Content),
        Some(s)
            if s.eq_ignore_ascii_case("bo")
                || s.eq_ignore_ascii_case("alloc")
                || s.eq_ignore_ascii_case("page") =>
        {
            Ok(LabInstrSizeMode::Bo)
        }
        Some(s) => Err(format!(
            "unknown XDNA2_LAB_INSTR_SIZE_MODE={s:?}; expected content|bo \
             (aliases alloc|page→bo)"
        )),
    }
}

/// Convenience: unset/empty → content; **unknown panics not used** — prefer try.
///
/// Deprecated for residual HITL env: use [`try_lab_instr_size_mode_from_str`].
/// Retained for pure defaults when input is known-good or None.
#[must_use]
pub fn lab_instr_size_mode_from_str(raw: Option<&str>) -> LabInstrSizeMode {
    try_lab_instr_size_mode_from_str(raw).unwrap_or(LabInstrSizeMode::Content)
}

/// Read process env `XDNA2_LAB_INSTR_SIZE_MODE` (fail-closed on unknown).
///
/// # Errors
///
/// Unknown token set in env.
pub fn lab_instr_size_mode_from_env() -> Result<LabInstrSizeMode, String> {
    try_lab_instr_size_mode_from_str(std::env::var("XDNA2_LAB_INSTR_SIZE_MODE").ok().as_deref())
}

/// Resolve START_NPU instruction size field (pure).
///
/// - `content` → `min(content_len, bo_alloc)` when both non-zero (never advertise
///   DMA longer than written BO bytes); zero content falls back to `bo_alloc`
/// - `bo` → `bo_alloc` (e.g. 4096)
///
/// Floor is 1 when both inputs are zero (refuse-class footgun for callers to detect).
#[must_use]
pub fn resolve_start_npu_inst_size(content_len: u32, bo_alloc: u32, mode: LabInstrSizeMode) -> u32 {
    match mode {
        LabInstrSizeMode::Bo => bo_alloc.max(1),
        LabInstrSizeMode::Content => {
            if content_len == 0 {
                bo_alloc.max(1)
            } else if bo_alloc == 0 {
                content_len.max(1)
            } else {
                content_len.min(bo_alloc)
            }
        }
    }
}

/// True when content mode would clamp `content_len` down to `bo_alloc`.
#[must_use]
pub fn instr_size_content_clamped(content_len: u32, bo_alloc: u32, mode: LabInstrSizeMode) -> bool {
    matches!(mode, LabInstrSizeMode::Content)
        && content_len > 0
        && bo_alloc > 0
        && content_len > bo_alloc
}

/// Format size dual-mode detail fragment (no secrets).
#[must_use]
pub fn format_instr_size_detail(
    mode: LabInstrSizeMode,
    content_len: u32,
    bo_alloc: u32,
    start_npu_size: u32,
) -> String {
    format!(
        "inst_size_mode={} content_size={content_len}B bo_size={bo_alloc}B \
         start_npu_size={start_npu_size}B",
        mode.as_str()
    )
}

/// Unit/API research helper for APP_LOAD residual classification strings.
///
/// **Not** auto-wired into live timed `detail` / `last_apply` paths — call sites
/// may adopt later. Pure string only; never claims Pass, C-ready, or
/// `ran_on_npu`. Encodes locked residual [`AIE2_FW_APP_LOAD_PDI_FAIL`] /
/// `APP_LOAD_PDI_FAIL` plus START_NPU size dual-mode fields. Env layout/size
/// trials are **CLOSED**.
#[must_use]
pub fn format_app_load_residual_diag(
    aiebu_elf: bool,
    rela_count: usize,
    size_mode: LabInstrSizeMode,
    content_len: u32,
    bo_alloc: u32,
    rela_mode: LabRelaMode,
    layout: &str,
) -> String {
    let start = resolve_start_npu_inst_size(content_len, bo_alloc, size_mode);
    let size = format_instr_size_detail(size_mode, content_len, bo_alloc, start);
    let layout = if layout.is_empty() { "na" } else { layout };
    format!(
        "app_load_residual code=0x{:x} name={} aiebu_elf={} rela_count={} \
         rela_mode={} layout={layout}; {size}; env_hitl_closed=1 \
         content_and_xrt3_closed=1 not_c_ready=1 not_ran_on_npu=1",
        AIE2_FW_APP_LOAD_PDI_FAIL,
        aie2_fw_status_name(AIE2_FW_APP_LOAD_PDI_FAIL),
        u8::from(aiebu_elf),
        rela_count,
        rela_mode.as_str(),
    )
}

/// Offline residual class from `last_apply.json` / timed `detail` signals.
///
/// Pure research enum — **never** means C-ready or product Pass. Use
/// [`classify_last_apply_residual`] / [`parse_last_apply_detail_signals`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SiliconResidualClass {
    /// aiebu ELF **and** rela evidence (`rela_count>0` or `aiebu_rela_patched`)
    /// **and** ERT Error → locked APP_LOAD residual class (journal often
    /// `0x3000003`; do not invent code without detail/journal).
    AppLoadPdiFailAfterAiebu,
    /// Raw / non-ELF blob + ERT Error — classic raw-bin APP_LOAD class (heuristic).
    AppLoadLikelyRawOrUnpatched,
    /// ERT Error without enough aiebu+rela classification (unknown blob, or
    /// aiebu without rela evidence).
    ErtErrorUnknownBlob,
    /// Timed path report without ERT Error marker but no Pass (e.g. OFM refuse).
    NotPassNoErtError,
    /// Insufficient signals to classify.
    Unclassified,
}

impl SiliconResidualClass {
    /// Stable token for docs / scripts (never `ran_on_npu` / C-ready).
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::AppLoadPdiFailAfterAiebu => "app_load_pdi_fail_after_aiebu",
            Self::AppLoadLikelyRawOrUnpatched => "app_load_likely_raw_or_unpatched",
            Self::ErtErrorUnknownBlob => "ert_error_unknown_blob",
            Self::NotPassNoErtError => "not_pass_no_ert_error",
            Self::Unclassified => "unclassified",
        }
    }

    /// True when this class is the locked ELF+rela APP_LOAD residual.
    #[must_use]
    pub const fn is_locked_app_load_after_aiebu(self) -> bool {
        matches!(self, Self::AppLoadPdiFailAfterAiebu)
    }
}

/// Parsed signals from a timed `detail` string (best-effort, pure).
///
/// Research bag of optional tokens — several independent presence flags are
/// expected (not a state machine).
#[allow(clippy::struct_excessive_bools)]
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct LastApplyDetailSignals {
    /// `ert_state=N` numeric when present (first `ert_state=` only).
    pub ert_state: Option<u32>,
    /// True when **first** `ert_state=` token is Error (name or numeric 5).
    pub ert_error: bool,
    /// `aiebu_elf=0|1` when present.
    pub aiebu_elf: Option<bool>,
    /// `rela_count=N` when present.
    pub rela_count: Option<usize>,
    /// True when `aiebu_rela_patched` token appears (userspace rela path ran).
    pub aiebu_rela_patched: bool,
    /// Bare `layout=` token (`count4` / `xrt3` / …) when found.
    pub layout: Option<String>,
    /// `inst_size_mode=content|bo` when found.
    pub inst_size_mode: Option<String>,
    /// Exact `ran_on_npu=true|false` token when found — **never invent true**.
    pub ran_on_npu: Option<bool>,
    /// `raw_nonzero_bytes=N` from ofm_stats when found.
    pub ofm_raw_nonzero_bytes: Option<u64>,
    /// Known FW status hex found in detail (`0x3000003` / `0x4000003`), if any.
    pub fw_status_code: Option<u32>,
    /// First `map_offset=` (fixture: instruction Dev BO; often `0xffffffffffffffff`).
    pub instr_map_offset: Option<u64>,
    /// First `ty=` buffer type token (fixture instr: `Dev`).
    pub instr_bo_type: Option<String>,
    /// First `xdna_addr=` after instr context (or first in detail).
    pub instr_xdna_addr: Option<u64>,
    /// `content_size=N` or first `content=N` size (bytes, `B` suffix optional).
    pub content_size_b: Option<u32>,
    /// First `bo_size=N` (instruction BO alloc; often page-padded 4096).
    pub bo_size_b: Option<u32>,
    /// `start_npu_size=N` START_NPU buffer_size field.
    pub start_npu_size_b: Option<u32>,
    /// True when detail contains `SubmitWaitNotOk` (OFM refuse after WAIT).
    pub submit_wait_not_ok: bool,
    /// `rela_mode=overwrite|add` when found.
    pub rela_mode: Option<String>,
    /// `config_cu=0|1` lab CONFIG_CU attach token when present (research; ≠ Pass).
    pub config_cu: Option<u8>,
    /// True when detail/status indicates CONFIG_CU attach failed (research only).
    pub config_cu_failed: bool,
    /// `pdi_bytes=N` when present (opaque PDI length after lab attach).
    pub pdi_bytes: Option<u32>,
    /// `cu_func=N` when present (0–255).
    pub cu_func: Option<u8>,
}

/// End of first whitespace/`;`/`,`/`)`/`:`/`(`/`+` delimited token.
///
/// Stops on trailing punctuation so live WAIT shapes like
/// `request=0xc0106449):` yield a clean value for parsers.
#[must_use]
fn detail_token_end(s: &str) -> usize {
    s.find(|c: char| {
        c.is_whitespace()
            || c == ';'
            || c == ','
            || c == ']'
            || c == ')'
            || c == '('
            || c == ':'
            || c == '+'
    })
    .unwrap_or(s.len())
}

/// Parse `0x…` / decimal token as `u64` (first token only).
///
/// Strips trailing non-hex / non-digit punctuation so detail strings that end
/// with `):` or `)` (common on WAIT_CMD) still parse. Full 16-nibble hex
/// (e.g. `map_offset=0xffffffffffffffff`) remains valid.
#[must_use]
fn parse_detail_u64_token(tok: &str) -> Option<u64> {
    let t = tok.trim();
    if t.is_empty() {
        return None;
    }
    if let Some(hex) = t.strip_prefix("0x").or_else(|| t.strip_prefix("0X")) {
        // Live WAIT often keeps `request=0xc0106449):` — drop trailing punct.
        let hex = hex.trim_end_matches(|c: char| !c.is_ascii_hexdigit());
        if hex.is_empty() {
            return None;
        }
        return u64::from_str_radix(hex, 16).ok();
    }
    let dec = t.trim_end_matches(|c: char| !c.is_ascii_digit());
    if dec.is_empty() {
        return None;
    }
    dec.parse::<u64>().ok()
}

/// Parse size token `1688` / `1688B` / `1688b` as `u32` bytes.
#[must_use]
fn parse_detail_size_bytes_token(tok: &str) -> Option<u32> {
    let t = tok.trim();
    let t = t
        .strip_suffix('B')
        .or_else(|| t.strip_suffix('b'))
        .unwrap_or(t)
        .trim();
    if t.is_empty() {
        return None;
    }
    t.parse::<u32>().ok()
}

/// First value after `key=` as a delimited token, or `None`.
#[must_use]
fn detail_first_token_after<'a>(detail: &'a str, key: &str) -> Option<&'a str> {
    let i = detail.find(key)?;
    let rest = &detail[i + key.len()..];
    let tok = &rest[..detail_token_end(rest)];
    let tok = tok.trim();
    if tok.is_empty() { None } else { Some(tok) }
}

/// True when instruction BO `map_offset` is the DRM "no host mmap" sentinel.
///
/// Live XDNA2 Dev-type instruction BOs commonly report
/// `map_offset=0xffffffffffffffff` (`u64::MAX`) — filled via DevHeap, not
/// GEM mmap. **Not** an APP_LOAD root cause by itself.
#[must_use]
pub fn instr_map_offset_is_no_mmap(offset: u64) -> bool {
    offset == u64::MAX
}

/// True when signals show userspace rela evidence.
#[must_use]
pub fn last_apply_has_rela_evidence(sig: &LastApplyDetailSignals) -> bool {
    sig.aiebu_rela_patched || sig.rela_count.is_some_and(|n| n > 0)
}

/// True when content/start_npu sizes agree (content-mode START_NPU honesty).
#[must_use]
pub fn last_apply_start_npu_matches_content(sig: &LastApplyDetailSignals) -> bool {
    match (sig.content_size_b, sig.start_npu_size_b) {
        (Some(c), Some(s)) => c == s && c > 0,
        _ => false,
    }
}

/// True when BO alloc is strictly larger than content (`bo_size > content_size`).
///
/// Research only — does **not** prove page-alignment; token is `bo_gt_content=1`.
#[must_use]
pub fn last_apply_bo_gt_content(sig: &LastApplyDetailSignals) -> bool {
    match (sig.content_size_b, sig.bo_size_b) {
        (Some(c), Some(b)) => b > c && c > 0,
        _ => false,
    }
}

/// Coarse last_apply fingerprint for C3 "no new C2 evidence" detection.
///
/// Compares `status` / `aiebu_elf` / `ert_error` / `ran_on_npu` / `detail` length /
/// optional top-level `rela_count` / **`config_cu_present`** (CONFIG_CU attach
/// signal so a post-P4 sandwich with `config_cu=` is not false C3_SKIP when
/// other fields coincidentally match). **Not** a full-body hash and **not** new
/// APP_LOAD research — only detects whether a snapshot matches another (or the
/// locked baseline shape). Never claims Pass / C-ready / `ran_on_npu`.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct LastApplyEvidenceFingerprint {
    /// Top-level or status string (trimmed); empty → `None`.
    pub status: Option<String>,
    /// Top-level `aiebu_elf` when known.
    pub aiebu_elf: Option<bool>,
    /// Top-level `ert_error` when known.
    pub ert_error: Option<bool>,
    /// Top-level `ran_on_npu` when known — never invent `true` for Pass.
    pub ran_on_npu: Option<bool>,
    /// Byte length of `detail` (0 when absent).
    pub detail_len: usize,
    /// Schema-2 top-level `rela_count` when provided (detail rela is not re-parsed).
    pub rela_count: Option<u32>,
    /// True when status/detail show a lab CONFIG_CU attempt (`config_cu=` /
    /// `config_cu_failed` / status `config_cu_failed`). Locked baseline = false.
    pub config_cu_present: bool,
}

/// True when status/detail carry a lab CONFIG_CU attach signal (research only).
///
/// Detects: top-level status `config_cu_failed`, detail `config_cu=…`, or
/// `config_cu_failed` token / "CONFIG_CU attach failed" phrase. Never invents
/// Pass / C-ready / `ran_on_npu`.
#[must_use]
pub fn last_apply_has_config_cu_signal(status: Option<&str>, detail: Option<&str>) -> bool {
    if status
        .map(str::trim)
        .is_some_and(|s| s.eq_ignore_ascii_case("config_cu_failed"))
    {
        return true;
    }
    let Some(d) = detail else {
        return false;
    };
    if d.contains("config_cu=") {
        return true;
    }
    // Whole-token `config_cu_failed` (not a longer identifier).
    if let Some(i) = d.find("config_cu_failed") {
        let before_ok = i == 0
            || d.as_bytes()
                .get(i - 1)
                .is_some_and(|b| !b.is_ascii_alphanumeric() && *b != b'_');
        let after = i + "config_cu_failed".len();
        let after_ok = d
            .as_bytes()
            .get(after)
            .is_none_or(|b| !b.is_ascii_alphanumeric() && *b != b'_');
        if before_ok && after_ok {
            return true;
        }
    }
    // Live fail detail phrase from timed path (no bare token).
    d.to_ascii_lowercase().contains("config_cu attach failed")
}

/// True when parsed detail signals show CONFIG_CU attach evidence.
///
/// Aligned with [`last_apply_has_config_cu_signal`] / C3 fingerprint `config_cu`
/// bit: `config_cu=` token and/or `config_cu_failed` only. Bare `pdi_bytes=` /
/// `cu_func=` alone do **not** set present (lab always emits `config_cu=` with
/// PDI size; checklist may still print those fields when parsed).
#[must_use]
pub fn last_apply_config_cu_present(sig: &LastApplyDetailSignals) -> bool {
    sig.config_cu.is_some() || sig.config_cu_failed
}

/// Merge top-level `status` into CONFIG_CU signals (e.g. `config_cu_failed`).
///
/// Pure; does not invent Pass. Call after [`parse_last_apply_detail_signals`].
pub fn merge_last_apply_status_config_cu(status: Option<&str>, sig: &mut LastApplyDetailSignals) {
    if status
        .map(str::trim)
        .is_some_and(|s| s.eq_ignore_ascii_case("config_cu_failed"))
    {
        sig.config_cu_failed = true;
    }
}

/// Build a coarse fingerprint from last_apply field slices (pure; no I/O).
#[must_use]
pub fn last_apply_evidence_fingerprint(
    status: Option<&str>,
    aiebu_elf: Option<bool>,
    ert_error: Option<bool>,
    ran_on_npu: Option<bool>,
    detail: Option<&str>,
    rela_count: Option<u32>,
) -> LastApplyEvidenceFingerprint {
    let status_owned = status
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_owned);
    LastApplyEvidenceFingerprint {
        status: status_owned,
        aiebu_elf,
        ert_error,
        ran_on_npu,
        detail_len: detail.map_or(0, str::len),
        rela_count,
        config_cu_present: last_apply_has_config_cu_signal(status, detail),
    }
}

/// True when two coarse fingerprints match (same C3 evidence identity).
///
/// Equality of status / aiebu / ert / ran_on_npu / detail_len / rela_count /
/// `config_cu_present` only.
#[must_use]
pub fn last_apply_is_same_fixture_fingerprint(
    a: &LastApplyEvidenceFingerprint,
    b: &LastApplyEvidenceFingerprint,
) -> bool {
    a == b
}

/// True when fields match the **locked** baseline APP_LOAD residual shape
/// (`ert_cmd_error` + aiebu + ert_error + `ran_on_npu=false` + class
/// [`SiliconResidualClass::AppLoadPdiFailAfterAiebu`]).
///
/// Used by C3 skip when only the repo fixture (or identical shape) is present —
/// does **not** expand the closed APP_LOAD signal matrix and never unlocks C.
#[must_use]
pub fn last_apply_matches_locked_app_load_baseline(
    status: Option<&str>,
    aiebu_elf: Option<bool>,
    ert_error: Option<bool>,
    ran_on_npu: Option<bool>,
    detail: Option<&str>,
    rela_count: Option<u32>,
) -> bool {
    if aiebu_elf != Some(true) || ert_error != Some(true) || ran_on_npu != Some(false) {
        return false;
    }
    let status_ok = status.is_some_and(|s| {
        let t = s.trim();
        t.eq_ignore_ascii_case("ert_cmd_error") || t.eq_ignore_ascii_case("ert_error")
    });
    if !status_ok {
        return false;
    }
    let rela_usize = rela_count.map(|n| n as usize);
    let class = classify_last_apply_residual_ex(status, detail, aiebu_elf, ert_error, rela_usize);
    class == SiliconResidualClass::AppLoadPdiFailAfterAiebu
}

/// True when a journal (or detail) line is a soft APP_LOAD / Failed-cmd hint.
///
/// Research-only filter for C3 `journal_hint=` print — **never** invents a FW
/// code into residual class without a detail field.
#[must_use]
pub fn journal_line_has_app_load_hint(line: &str) -> bool {
    let l = line.to_ascii_lowercase();
    l.contains("0x3000003")
        || l.contains("0x4000003")
        || l.contains("app_load")
        || l.contains("failed cmd")
        || l.contains("status 0x3000003")
        || l.contains("status 0x4000003")
}

// ---------------------------------------------------------------------------
// Progressive last_apply status tokens (mid-path stamp; ≠ Pass)
// ---------------------------------------------------------------------------

/// Progressive last_apply after CREATE_HWCTX returned OK (before EXEC).
pub const LAB_PARTIAL_STATUS_HWCTX_OK: &str = "lab_partial_hwctx_ok";
/// Progressive last_apply after optional CONFIG_CU attach OK (before EXEC).
pub const LAB_PARTIAL_STATUS_CONFIG_CU: &str = "lab_partial_config_cu";
/// Progressive last_apply immediately before `submit_and_wait_command`.
pub const LAB_PARTIAL_STATUS_PRE_SUBMIT: &str = "lab_partial_pre_submit";

/// Honesty fragment required on every progressive / incomplete last_apply.
///
/// Hard-coded on partial stamps and journal soft notes. **Never** product Pass.
#[must_use]
pub const fn lab_partial_honesty_tokens() -> &'static str {
    "invent_pass=0 not_ran_on_npu=1 not_c_ready=1"
}

/// True when `status` is a mid-path progressive stamp name (research only).
#[must_use]
pub fn is_lab_partial_progressive_status(status: &str) -> bool {
    matches!(
        status,
        LAB_PARTIAL_STATUS_HWCTX_OK | LAB_PARTIAL_STATUS_CONFIG_CU | LAB_PARTIAL_STATUS_PRE_SUBMIT
    )
}

/// Build detail text for a progressive last_apply stamp (pure; offline).
///
/// Always includes [`lab_partial_honesty_tokens`]. Callers may append stage notes.
#[must_use]
pub fn format_lab_partial_detail(stage_note: &str) -> String {
    let note = stage_note.trim();
    if note.is_empty() {
        format!(
            "progressive last_apply stamp; {}; kill mid-ioctl can still lose stage",
            lab_partial_honesty_tokens()
        )
    } else {
        format!(
            "{note}; progressive last_apply stamp; {}; kill mid-ioctl can still lose stage",
            lab_partial_honesty_tokens()
        )
    }
}

// ---------------------------------------------------------------------------
// Journal soft taxonomy (timeout / IO_PAGE_FAULT / aie2_set_cmd_timeout)
// ---------------------------------------------------------------------------

/// Soft residual class token for incomplete outer-kill / journal-only evidence.
///
/// **Never** equals locked APP_LOAD, PassCandidate, or product Pass.
pub const JOURNAL_SOFT_INCOMPLETE_CLASS: &str = "incomplete_timeout_or_journal";

/// Soft signals from kernel journal / operator paste (research only).
///
/// Live 2026-08-09 shot: outer timeout kill + `IO_PAGE_FAULT` +
/// `aie2_set_cmd_timeout`. These tokens **never** invent product Pass or map
/// journal-only text to locked APP_LOAD without a finished last_apply snapshot.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct JournalSoftTaxonomy {
    /// Outer process kill / timeout (`timeout(1)` rc=124, outer kill language).
    pub incomplete_outer_kill: bool,
    /// Kernel `IO_PAGE_FAULT` (amdxdna / IOMMU) in the paste.
    pub io_page_fault: bool,
    /// Firmware `aie2_set_cmd_timeout` (or close spelling) in the paste.
    pub aie2_set_cmd_timeout: bool,
}

impl JournalSoftTaxonomy {
    /// True when any recognized soft signal is present.
    #[must_use]
    pub const fn has_any(&self) -> bool {
        self.incomplete_outer_kill || self.io_page_fault || self.aie2_set_cmd_timeout
    }

    /// Soft residual class token when signals present; else `unclassified`.
    ///
    /// **Never** returns locked APP_LOAD class from journal alone.
    #[must_use]
    pub fn soft_residual_class_token(&self) -> &'static str {
        if self.has_any() {
            JOURNAL_SOFT_INCOMPLETE_CLASS
        } else {
            SiliconResidualClass::Unclassified.as_str()
        }
    }

    /// Soft report line — always honesty trio; never Pass / C-ready.
    #[must_use]
    pub fn format_soft_note(&self) -> String {
        format!(
            "journal_soft_tax class={} incomplete_outer_kill={} io_page_fault={} \
             aie2_set_cmd_timeout={} {} product_pass_requires_live_decide=1",
            self.soft_residual_class_token(),
            u8::from(self.incomplete_outer_kill),
            u8::from(self.io_page_fault),
            u8::from(self.aie2_set_cmd_timeout),
            lab_partial_honesty_tokens(),
        )
    }
}

/// Classify multi-line journal / operator paste for timeout soft signals.
///
/// Pure offline research. **Never** invents Pass, C-ready, or locked APP_LOAD
/// residual class from journal text alone.
#[must_use]
pub fn classify_journal_soft_signals(text: &str) -> JournalSoftTaxonomy {
    let lower = text.to_ascii_lowercase();
    let incomplete_outer_kill = lower.contains("killed by timeout")
        || lower.contains("outer timeout")
        || lower.contains("timeout kill")
        || lower.contains("rc=124")
        || lower.contains("exit 124")
        || lower.contains("exit_code=124")
        || lower.contains("lab exit 4")
        || (lower.contains("timeout")
            && lower.contains("npu_direct_bench")
            && lower.contains("124"));
    let io_page_fault = lower.contains("io_page_fault") || lower.contains("io page fault");
    let aie2_set_cmd_timeout =
        lower.contains("aie2_set_cmd_timeout") || lower.contains("aie2 set cmd timeout");
    JournalSoftTaxonomy {
        incomplete_outer_kill,
        io_page_fault,
        aie2_set_cmd_timeout,
    }
}

// ---------------------------------------------------------------------------
// T3b — IO_PAGE_FAULT vs last_apply BO map (+ optional rela targets) audit
// ---------------------------------------------------------------------------
//
// Pure residual science only. Never product Pass / never `ran_on_npu`.
// Live 2026-08-10 pin: fault `0x2fff80007f40` vs DevHeap/instr/host UVAs → orphan.

/// Default DevHeap span when building fault map spans from bo_diag (64 MiB heap).
pub const BO_DIAG_DEFAULT_DEVHEAP_SIZE: u64 = 64 * 1024 * 1024;
/// Default instruction BO span (page-padded lab instr BO).
pub const BO_DIAG_DEFAULT_INSTR_SIZE: u64 = 4096;
/// Near-base neighborhood when fault is outside known size but close to a base.
pub const FAULT_NEAR_BO_BASE_WINDOW: u64 = 4096;

/// Soft residual token for orphan / map-mismatch journal faults (research only).
///
/// **Never** locked APP_LOAD, PassCandidate, or product Pass.
pub const IO_PAGE_FAULT_MAP_AUDIT_CLASS: &str = "io_page_fault_vs_bo_map";

/// One entry from last_apply `bo_diag=[label: … xdna_addr=0x…; …]`.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct BoDiagEntry {
    /// Label (`DevHeap`, `instr`, `ifm`, `wts`, `ofm`, `ctrl`, …).
    pub label: String,
    /// Device / PASID address when present and parseable.
    pub xdna_addr: Option<u64>,
    /// Host vaddr when present.
    pub vaddr: Option<u64>,
    /// Type hint (`DevHeap`, `Dev`, `Shmem`, …).
    pub ty: Option<String>,
    /// BO handle when present.
    pub handle: Option<u32>,
}

/// Known BO base + size for span classification.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BoSpan {
    /// Label (same as bo_diag label when built from diag).
    pub label: String,
    /// Base `xdna_addr`.
    pub base: u64,
    /// Length in bytes (`[base, base+size)`).
    pub size: u64,
}

impl BoSpan {
    /// Construct from static label (unit tests / call sites).
    #[must_use]
    pub fn new(label: impl Into<String>, base: u64, size: u64) -> Self {
        Self {
            label: label.into(),
            base,
            size,
        }
    }
}

/// Classification of one journal fault address vs BO map / rela targets.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FaultMapClass {
    /// Fault falls in `[base, base+size)` for a labeled BO.
    InBoSpan {
        /// BO label from `bo_diag` (e.g. `ifm`, `instr`).
        label: String,
    },
    /// Fault is within [`FAULT_NEAR_BO_BASE_WINDOW`] of a base but outside size.
    NearBoBase {
        /// BO label whose base is nearest within the near window.
        label: String,
    },
    /// Fault equals an overwrite rela patch value `(base[sym]+addend)`.
    MatchesRelaTarget {
        /// Dynsym index used for the rela base.
        sym: u32,
        /// Rela offset field (bytes into ctrltext / as recorded).
        offset: u32,
    },
    /// None of the above (11bc9016 live shape for `0x2fff80007f40`).
    Orphan,
}

impl FaultMapClass {
    /// Stable token for soft notes.
    #[must_use]
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::InBoSpan { .. } => "in_bo_span",
            Self::NearBoBase { .. } => "near_bo_base",
            Self::MatchesRelaTarget { .. } => "matches_rela_target",
            Self::Orphan => "orphan",
        }
    }
}

/// One classified fault address.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FaultClassified {
    /// Journal fault address.
    pub fault: u64,
    /// Map class.
    pub class: FaultMapClass,
}

/// Composite offline audit: last_apply bo_diag + journal faults (+ optional rela).
///
/// Research only. Soft note always carries honesty trio. **Never** product Pass.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct IoPageFaultMapAudit {
    /// Parsed bo_diag entries (may be empty).
    pub bo_entries: Vec<BoDiagEntry>,
    /// Spans used for classification.
    pub spans: Vec<BoSpan>,
    /// Fault addresses from journal (or empty).
    pub fault_addrs: Vec<u64>,
    /// Per-fault classification.
    pub classes: Vec<FaultClassified>,
    /// Number of overwrite rela targets when ELF supplied and listed.
    pub rela_targets_count: Option<usize>,
    /// Count of orphan faults.
    pub orphan_count: usize,
    /// Count of in-span faults.
    pub in_span_count: usize,
    /// Count of near-base faults.
    pub near_base_count: usize,
    /// Count of rela-target matches.
    pub rela_match_count: usize,
}

impl IoPageFaultMapAudit {
    /// Soft residual class token — map audit class when faults present, else unclassified.
    ///
    /// **Never** returns locked APP_LOAD from this audit alone.
    #[must_use]
    pub fn soft_residual_class_token(&self) -> &'static str {
        if self.fault_addrs.is_empty() && self.bo_entries.is_empty() {
            SiliconResidualClass::Unclassified.as_str()
        } else {
            IO_PAGE_FAULT_MAP_AUDIT_CLASS
        }
    }

    /// Soft report line — always honesty trio; audit alone ≠ Pass.
    #[must_use]
    pub fn format_soft_note(&self) -> String {
        let mut class_parts: Vec<String> = self
            .classes
            .iter()
            .map(|c| format!("0x{:x}:{}", c.fault, c.class.as_str()))
            .collect();
        if class_parts.is_empty() {
            class_parts.push("none".into());
        }
        format!(
            "io_page_fault_map_audit class={} faults={} orphan={} in_span={} \
             near_base={} rela_match={} rela_targets={} bo_entries={} classes=[{}] \
             invent_pass=0 not_c_ready=1 not_ran_on_npu=1 \
             product_pass_requires_live_decide=1 audit_alone_not_pass=1",
            self.soft_residual_class_token(),
            self.fault_addrs.len(),
            self.orphan_count,
            self.in_span_count,
            self.near_base_count,
            self.rela_match_count,
            self.rela_targets_count
                .map_or_else(|| "absent".into(), |n| n.to_string()),
            self.bo_entries.len(),
            class_parts.join(","),
        )
    }
}

/// Parse hex token (`0x…` / bare hex) → `u64`.
fn parse_hex_u64_token(raw: &str) -> Option<u64> {
    let s = raw.trim().trim_end_matches([',', ';', ']', ')', '"', '\'']);
    if s.is_empty() {
        return None;
    }
    let s = s
        .strip_prefix("0x")
        .or_else(|| s.strip_prefix("0X"))
        .unwrap_or(s);
    u64::from_str_radix(s, 16).ok()
}

/// Extract the body inside `bo_diag=[...]` (first `[` after key through matching `]`).
fn bo_diag_bracket_body(detail: &str) -> Option<&str> {
    let key = "bo_diag=";
    let start = detail.find(key)?;
    let after = &detail[start + key.len()..];
    let after = after.trim_start();
    if !after.starts_with('[') {
        return None;
    }
    let inner = &after[1..];
    let end = inner.find(']')?;
    Some(&inner[..end])
}

/// Parse `bo_diag=[DevHeap: … xdna_addr=0x…; instr: …]` from last_apply detail.
///
/// Pure offline. Missing / unparseable → empty vec (never invents paddrs).
#[must_use]
pub fn parse_bo_diag_from_detail(detail: &str) -> Vec<BoDiagEntry> {
    let Some(body) = bo_diag_bracket_body(detail) else {
        return Vec::new();
    };
    let mut out = Vec::new();
    for part in body.split(';') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        let Some((label_raw, rest)) = part.split_once(':') else {
            continue;
        };
        let label = label_raw.trim();
        if label.is_empty() {
            continue;
        }
        let mut entry = BoDiagEntry {
            label: label.to_string(),
            ..BoDiagEntry::default()
        };
        for tok in rest.split_whitespace() {
            let Some((k, v)) = tok.split_once('=') else {
                continue;
            };
            match k {
                "xdna_addr" => entry.xdna_addr = parse_hex_u64_token(v),
                "vaddr" => entry.vaddr = parse_hex_u64_token(v),
                "ty" => {
                    entry.ty = Some(v.trim_end_matches([',', ';']).to_string());
                }
                "handle" => {
                    let v = v.trim_end_matches([',', ';']);
                    entry.handle = v
                        .parse::<u32>()
                        .ok()
                        .or_else(|| parse_hex_u64_token(v).and_then(|n| u32::try_from(n).ok()));
                }
                _ => {}
            }
        }
        out.push(entry);
    }
    out
}

/// Staged-size default for a bo_diag label (bytes); `None` if unknown.
#[must_use]
pub fn default_bo_diag_size_for_label(label: &str) -> Option<u64> {
    match label.trim() {
        "DevHeap" | "devheap" | "DEVHEAP" => Some(BO_DIAG_DEFAULT_DEVHEAP_SIZE),
        "instr" | "Instr" | "INSTR" => Some(BO_DIAG_DEFAULT_INSTR_SIZE),
        "ifm" | "IFM" => Some(STAGED_MLADF_IFM_BYTES),
        "wts" | "WTS" => Some(STAGED_MLADF_WTS_BYTES),
        "ofm" | "OFM" => Some(STAGED_MLADF_OFM_BYTES),
        "ctrl" | "CTRL" => Some(STAGED_MLADF_CTRL_BYTES),
        _ => None,
    }
}

/// Build spans from parsed bo_diag entries (staged sizes when label known).
#[must_use]
pub fn bo_spans_from_diag_entries(entries: &[BoDiagEntry]) -> Vec<BoSpan> {
    let mut out = Vec::new();
    for e in entries {
        let Some(base) = e.xdna_addr.filter(|&a| is_valid_device_paddr(a)) else {
            continue;
        };
        let size = default_bo_diag_size_for_label(&e.label).unwrap_or(FAULT_NEAR_BO_BASE_WINDOW);
        out.push(BoSpan::new(e.label.clone(), base, size));
    }
    out
}

/// Extract IO_PAGE_FAULT-related hex addresses from journal / operator paste.
///
/// Prefers `address=0x…` tokens on lines that mention `IO_PAGE_FAULT` (AMD-Vi).
/// When no `address=` token exists on a fault line, also collects bare `0x…`
/// tokens ≥ 12 hex digits on that line (avoids small flag/domain values).
/// Empty / no IO_PAGE_FAULT → empty vec. Pure; never invents Pass.
#[must_use]
pub fn parse_journal_io_page_fault_addrs(text: &str) -> Vec<u64> {
    if text.is_empty() {
        return Vec::new();
    }
    let mut out: Vec<u64> = Vec::new();
    for line in text.lines() {
        let lower = line.to_ascii_lowercase();
        if !lower.contains("io_page_fault") && !lower.contains("io page fault") {
            continue;
        }
        // Prefer explicit address= tokens (AMD-Vi).
        let mut found_address_eq = false;
        let mut rest = line;
        while let Some(idx) = rest.to_ascii_lowercase().find("address=") {
            let after = &rest[idx + "address=".len()..];
            let token = after
                .split(|c: char| c.is_whitespace() || c == ']' || c == ',' || c == ';')
                .next()
                .unwrap_or("");
            if let Some(a) = parse_hex_u64_token(token) {
                if !out.contains(&a) {
                    out.push(a);
                }
                found_address_eq = true;
            }
            rest = &after[token.len().min(after.len())..];
            if rest.is_empty() {
                break;
            }
        }
        if found_address_eq {
            continue;
        }
        // Fallback: long hex tokens on the fault line only.
        for tok in line.split_whitespace() {
            let t = tok.trim_matches(|c: char| !c.is_ascii_hexdigit() && c != 'x' && c != 'X');
            if !(t.starts_with("0x") || t.starts_with("0X")) {
                continue;
            }
            let digits = &t[2..];
            if digits.len() < 12 {
                continue;
            }
            if let Some(a) = parse_hex_u64_token(t)
                && !out.contains(&a)
            {
                out.push(a);
            }
        }
    }
    out
}

/// Classify one fault address against BO spans and optional rela overwrite targets.
///
/// Priority: exact rela target → tightest in-span (smallest size) → nearest base
/// within [`FAULT_NEAR_BO_BASE_WINDOW`] → orphan.
///
/// Tightest-span wins so a page-sized `instr` BO inside a 64 MiB `DevHeap` is not
/// mis-labeled as DevHeap.
#[must_use]
pub fn classify_fault_addr(
    fault: u64,
    spans: &[BoSpan],
    rela_targets: &[(u32, u32, u64)],
) -> FaultMapClass {
    for &(sym, offset, value) in rela_targets {
        if value == fault {
            return FaultMapClass::MatchesRelaTarget { sym, offset };
        }
    }
    let mut best_span: Option<(String, u64)> = None; // (label, size)
    for s in spans {
        if s.size == 0 {
            continue;
        }
        let end = s.base.saturating_add(s.size);
        if fault >= s.base && fault < end {
            match &best_span {
                None => best_span = Some((s.label.clone(), s.size)),
                Some((_, sz)) if s.size < *sz => best_span = Some((s.label.clone(), s.size)),
                _ => {}
            }
        }
    }
    if let Some((label, _)) = best_span {
        return FaultMapClass::InBoSpan { label };
    }
    let mut best_near: Option<(String, u64)> = None; // (label, dist)
    for s in spans {
        let dist = fault.abs_diff(s.base);
        if dist < FAULT_NEAR_BO_BASE_WINDOW {
            match &best_near {
                None => best_near = Some((s.label.clone(), dist)),
                Some((_, d)) if dist < *d => best_near = Some((s.label.clone(), dist)),
                _ => {}
            }
        }
    }
    if let Some((label, _)) = best_near {
        return FaultMapClass::NearBoBase { label };
    }
    FaultMapClass::Orphan
}

/// List overwrite rela patch values: `(sym, ctrltext_offset, value=base[sym]+addend)`.
///
/// Same index map as live patch: `1→ifm, 2→wts, 3→ofm, 4→ctrl`. Pure; no mutate.
///
/// # Errors
///
/// When `.rela.dyn` cannot be parsed as ELF32 (empty rela is ok → empty vec).
pub fn list_rela_patch_targets_overwrite(
    elf: &[u8],
    ifm: u64,
    wts: u64,
    ofm: u64,
    ctrl: u64,
) -> Result<Vec<(u32, u32, u64)>, String> {
    let relas = parse_elf32_rela_dyn(elf).map_err(|e| e.to_string())?;
    let bases = [0_u64, ifm, wts, ofm, ctrl];
    let mut out = Vec::with_capacity(relas.len());
    for r in &relas {
        let sym = r.sym();
        let base = bases.get(sym as usize).copied().unwrap_or(0);
        #[allow(clippy::cast_sign_loss)] // XRT-style wrapping addend math
        let value = base.wrapping_add(r.addend as u64);
        out.push((sym, r.offset, value));
    }
    Ok(out)
}

/// Composite: parse bo_diag + journal faults (+ optional ELF rela list) and classify.
///
/// Research only. Empty journal → no fault classes. Empty elf → skip rela match.
/// Soft note always `invent_pass=0 not_c_ready=1 not_ran_on_npu=1`.
#[must_use]
pub fn audit_io_page_fault_vs_lab_map(
    detail: &str,
    journal: Option<&str>,
    elf: Option<&[u8]>,
) -> IoPageFaultMapAudit {
    let bo_entries = parse_bo_diag_from_detail(detail);
    let spans = bo_spans_from_diag_entries(&bo_entries);

    let mut rela_targets: Vec<(u32, u32, u64)> = Vec::new();
    let mut rela_targets_count: Option<usize> = None;
    if let Some(bytes) = elf.filter(|b| !b.is_empty()) {
        // Prefer io paddrs from detail for rela bases; else bo_diag labels.
        let (ifm, wts, ofm, ctrl) = parse_io_paddrs_from_detail(detail).unwrap_or_else(|| {
            let mut ifm = 0;
            let mut wts = 0;
            let mut ofm = 0;
            let mut ctrl = 0;
            for e in &bo_entries {
                if let Some(a) = e.xdna_addr {
                    match e.label.as_str() {
                        "ifm" | "IFM" => ifm = a,
                        "wts" | "WTS" => wts = a,
                        "ofm" | "OFM" => ofm = a,
                        "ctrl" | "CTRL" => ctrl = a,
                        _ => {}
                    }
                }
            }
            (ifm, wts, ofm, ctrl)
        });
        if is_valid_device_paddr(ifm) || is_valid_device_paddr(wts) || is_valid_device_paddr(ofm) {
            match list_rela_patch_targets_overwrite(bytes, ifm, wts, ofm, ctrl) {
                Ok(t) => {
                    rela_targets_count = Some(t.len());
                    rela_targets = t;
                }
                Err(_) => rela_targets_count = Some(0),
            }
        } else {
            rela_targets_count = Some(0);
        }
    }

    let fault_addrs = journal.map_or_else(Vec::new, parse_journal_io_page_fault_addrs);
    let mut classes = Vec::with_capacity(fault_addrs.len());
    let mut orphan_count = 0usize;
    let mut in_span_count = 0usize;
    let mut near_base_count = 0usize;
    let mut rela_match_count = 0usize;
    for &fault in &fault_addrs {
        let class = classify_fault_addr(fault, &spans, &rela_targets);
        match &class {
            FaultMapClass::Orphan => orphan_count += 1,
            FaultMapClass::InBoSpan { .. } => in_span_count += 1,
            FaultMapClass::NearBoBase { .. } => near_base_count += 1,
            FaultMapClass::MatchesRelaTarget { .. } => rela_match_count += 1,
        }
        classes.push(FaultClassified { fault, class });
    }

    IoPageFaultMapAudit {
        bo_entries,
        spans,
        fault_addrs,
        classes,
        rela_targets_count,
        orphan_count,
        in_span_count,
        near_base_count,
        rela_match_count,
    }
}

// ---------------------------------------------------------------------------
// T3c — research PDI identity honesty + offline fingerprint (not product Pass)
// ---------------------------------------------------------------------------

/// Soft residual class token: default dump / lab attach is research overlay only.
///
/// **Never** product known-good matmul PDI. **Never** Pass / `ran_on_npu`.
pub const RESEARCH_PDI_IDENTITY_CLASS: &str = "research_pdi_not_product_known_good";

/// Measured live size under `11bc9016` (`pdi_bytes=283840` CVML AIE2P research dump).
///
/// Size match alone ≠ product known-good and ≠ Pass.
pub const RESEARCH_PDI_DEFAULT_DUMP_BYTES: u64 = 283_840;

/// Soft fingerprint uses first 16 hex chars of SHA-256 (8 bytes).
pub const PDI_FINGERPRINT_SHA_PREFIX_HEX: usize = 16;

/// Source kind for research PDI identity (opaque; no PDI field decode).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum ResearchPdiSourceKind {
    /// No blob / no `pdi_bytes` signal.
    #[default]
    Absent,
    /// Default dump path: CVML / AIE2P research overlay (`dump_xclbin_pdi`).
    CvmlAie2pResearchOverlay,
    /// Opaque path or last_apply size only (not classified as product known-good).
    UnknownOpaque,
}

impl ResearchPdiSourceKind {
    /// Stable token for soft notes.
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Absent => "absent",
            Self::CvmlAie2pResearchOverlay => "cvml_aie2p_research_overlay",
            Self::UnknownOpaque => "unknown_opaque",
        }
    }
}

/// Pure PDI blob fingerprint: length + SHA-256 prefix (research only).
///
/// Digests only. **Not** FW decode. **Not** product known-good. **Not** Pass.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct PdiBlobFingerprint {
    /// Blob length in bytes.
    pub len_bytes: u64,
    /// First [`PDI_FINGERPRINT_SHA_PREFIX_HEX`] hex of SHA-256 (lowercase).
    /// Empty when digest refused or empty input.
    pub sha256_prefix16: String,
    /// Full 64-char lowercase hex when available; empty when refused.
    pub sha256_hex: String,
}

impl PdiBlobFingerprint {
    /// Soft token `pdi_fp len=N sha16=…` (sha16=`absent` when empty).
    #[must_use]
    pub fn format_token(&self) -> String {
        let sha = if self.sha256_prefix16.is_empty() {
            "absent"
        } else {
            self.sha256_prefix16.as_str()
        };
        format!("pdi_fp len={} sha16={sha}", self.len_bytes)
    }
}

/// Fingerprint opaque PDI bytes (len + sha256 prefix16). Empty data → len 0, empty sha.
#[must_use]
pub fn fingerprint_pdi_blob_bytes(data: &[u8]) -> PdiBlobFingerprint {
    let len_bytes = data.len() as u64;
    if data.is_empty() {
        return PdiBlobFingerprint {
            len_bytes: 0,
            sha256_prefix16: String::new(),
            sha256_hex: String::new(),
        };
    }
    let sha256_hex = sha256_hex_lower(data);
    let sha256_prefix16 = if sha256_hex.is_empty() {
        String::new()
    } else {
        sha256_hex
            .chars()
            .take(PDI_FINGERPRINT_SHA_PREFIX_HEX)
            .collect()
    };
    PdiBlobFingerprint {
        len_bytes,
        sha256_prefix16,
        sha256_hex,
    }
}

/// Research PDI identity scorecard (default dump ≠ product matmul known-good).
///
/// Soft always: `research_pdi_not_product_known_good=1 invent_pass=0 not_ran_on_npu=1`.
/// Attach measured ≠ Pass; wrong overlay may still IO_PAGE_FAULT / APP_LOAD.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct ResearchPdiIdentity {
    /// Where the bytes / size signal came from (research taxonomy).
    pub source_kind: ResearchPdiSourceKind,
    /// Length when known (`pdi_bytes=` or blob).
    pub len_bytes: Option<u64>,
    /// Fingerprint when full bytes supplied; `None` for size-only last_apply.
    pub fingerprint: Option<PdiBlobFingerprint>,
    /// Always `false` offline for research dumps (never invent product known-good).
    pub product_known_good: bool,
    /// True when `len_bytes == RESEARCH_PDI_DEFAULT_DUMP_BYTES` (11bc9016 shape).
    pub matches_live_research_dump_size: bool,
}

impl ResearchPdiIdentity {
    /// Soft residual class token (always research-not-product when bytes/size present).
    #[must_use]
    pub fn soft_residual_class_token(&self) -> &'static str {
        match self.source_kind {
            ResearchPdiSourceKind::Absent => "research_pdi_absent",
            _ => RESEARCH_PDI_IDENTITY_CLASS,
        }
    }

    /// Soft note for classify / preflight. Always honesty; never Pass.
    #[must_use]
    pub fn format_soft_note(&self) -> String {
        let fp = self
            .fingerprint
            .as_ref()
            .map_or_else(|| "fp=absent".into(), PdiBlobFingerprint::format_token);
        let len = self
            .len_bytes
            .map_or_else(|| "absent".into(), |n| n.to_string());
        format!(
            "research_pdi_identity class={} source={} len={} {fp} \
             research_pdi_not_product_known_good=1 product_known_good={} \
             matches_live_research_dump_size={} attach_measured_not_pass=1 \
             wrong_overlay_may_fault_or_app_load=1 invent_pass=0 not_c_ready=1 \
             not_ran_on_npu=1 product_pass_requires_live_decide=1",
            self.soft_residual_class_token(),
            self.source_kind.as_str(),
            len,
            u8::from(self.product_known_good),
            u8::from(self.matches_live_research_dump_size),
        )
    }
}

/// Soft preflight when `XDNA2_LAB_PDI_BLOB` is set (or last_apply had CONFIG_CU PDI).
///
/// Alias of [`ResearchPdiIdentity::format_soft_note`] for tool call sites.
#[must_use]
pub fn format_research_pdi_preflight_note(identity: &ResearchPdiIdentity) -> String {
    identity.format_soft_note()
}

/// Classify path/source hint for research dump vs unknown opaque.
///
/// Looks for CVML / AIE2P / `dump_xclbin_pdi` / `research_pdi` markers in the hint.
#[must_use]
pub fn research_pdi_source_kind_from_hint(hint: Option<&str>) -> ResearchPdiSourceKind {
    let Some(h) = hint.map(str::trim).filter(|s| !s.is_empty()) else {
        return ResearchPdiSourceKind::UnknownOpaque;
    };
    let lower = h.to_ascii_lowercase();
    if lower.contains("cvml")
        || lower.contains("aie2p")
        || lower.contains("dump_xclbin_pdi")
        || lower.contains("research_pdi")
        || lower.contains("amd_aie2p")
        || lower.contains("overlay")
    {
        ResearchPdiSourceKind::CvmlAie2pResearchOverlay
    } else {
        ResearchPdiSourceKind::UnknownOpaque
    }
}

/// Score research PDI from optional bytes + source hint.
///
/// Empty / missing bytes → [`ResearchPdiSourceKind::Absent`] when no size override.
/// Always `product_known_good=false`. Never invents Pass.
#[must_use]
pub fn research_pdi_identity_from_bytes(
    data: Option<&[u8]>,
    source_hint: Option<&str>,
) -> ResearchPdiIdentity {
    match data {
        None | Some([]) => ResearchPdiIdentity {
            source_kind: ResearchPdiSourceKind::Absent,
            len_bytes: None,
            fingerprint: None,
            product_known_good: false,
            matches_live_research_dump_size: false,
        },
        Some(bytes) => {
            let fp = fingerprint_pdi_blob_bytes(bytes);
            let len = fp.len_bytes;
            ResearchPdiIdentity {
                source_kind: research_pdi_source_kind_from_hint(source_hint),
                len_bytes: Some(len),
                fingerprint: Some(fp),
                product_known_good: false,
                matches_live_research_dump_size: len == RESEARCH_PDI_DEFAULT_DUMP_BYTES,
            }
        }
    }
}

/// Score from last_apply signals (+ optional full blob for sha prefix).
///
/// Size-only path when blob absent: still marks research-not-product when
/// `pdi_bytes` / `config_cu` present. Always `product_known_good=false`.
#[must_use]
pub fn research_pdi_identity_from_last_apply_signals(
    sig: &LastApplyDetailSignals,
    optional_blob: Option<&[u8]>,
    source_hint: Option<&str>,
) -> ResearchPdiIdentity {
    if let Some(bytes) = optional_blob.filter(|b| !b.is_empty()) {
        let mut id = research_pdi_identity_from_bytes(Some(bytes), source_hint);
        // Prefer live size token when present and disagrees (should not).
        if let Some(n) = sig.pdi_bytes {
            id.len_bytes = Some(u64::from(n));
            id.matches_live_research_dump_size = u64::from(n) == RESEARCH_PDI_DEFAULT_DUMP_BYTES;
        }
        return id;
    }
    if let Some(n) = sig.pdi_bytes {
        let len = u64::from(n);
        let kind = if source_hint.is_some() {
            research_pdi_source_kind_from_hint(source_hint)
        } else if len == RESEARCH_PDI_DEFAULT_DUMP_BYTES {
            // 11bc9016 default dump shape without path: still research overlay class.
            ResearchPdiSourceKind::CvmlAie2pResearchOverlay
        } else {
            ResearchPdiSourceKind::UnknownOpaque
        };
        return ResearchPdiIdentity {
            source_kind: kind,
            len_bytes: Some(len),
            fingerprint: None,
            product_known_good: false,
            matches_live_research_dump_size: len == RESEARCH_PDI_DEFAULT_DUMP_BYTES,
        };
    }
    if sig.config_cu.is_some() || sig.config_cu_failed {
        // CONFIG_CU attempted without size: still research attach, not product KG.
        return ResearchPdiIdentity {
            source_kind: research_pdi_source_kind_from_hint(source_hint).max_absent_to_unknown(),
            len_bytes: None,
            fingerprint: None,
            product_known_good: false,
            matches_live_research_dump_size: false,
        };
    }
    research_pdi_identity_from_bytes(None, None)
}

/// Default dump path locked identity (no bytes): CVML AIE2P research, not product KG.
///
/// Used by soft preflight / docs when only the default dump recipe is known.
#[must_use]
pub fn research_pdi_identity_default_dump_locked() -> ResearchPdiIdentity {
    ResearchPdiIdentity {
        source_kind: ResearchPdiSourceKind::CvmlAie2pResearchOverlay,
        len_bytes: Some(RESEARCH_PDI_DEFAULT_DUMP_BYTES),
        fingerprint: None,
        product_known_good: false,
        matches_live_research_dump_size: true,
    }
}

/// Parse soft `pdi_fp len=N sha16=HEX` or `pdi_fp_len=` / `pdi_fp_sha16=` from detail.
///
/// Missing → `None`. Pure offline; never invents product known-good.
#[must_use]
pub fn parse_pdi_fingerprint_from_detail(detail: &str) -> Option<PdiBlobFingerprint> {
    if detail.is_empty() {
        return None;
    }
    // Compact form: pdi_fp len=283840 sha16=abcdef0123456789
    if let Some(idx) = detail.find("pdi_fp ") {
        let rest = &detail[idx + "pdi_fp ".len()..];
        let mut len_bytes: Option<u64> = None;
        let mut sha16 = String::new();
        for tok in rest.split_whitespace() {
            if let Some(v) = tok.strip_prefix("len=") {
                let v = v.trim_end_matches([',', ';']);
                len_bytes = v.parse().ok();
            } else if let Some(v) = tok.strip_prefix("sha16=") {
                let v = v.trim_end_matches([',', ';']);
                if v != "absent" && !v.is_empty() {
                    sha16 = v.to_ascii_lowercase();
                }
            } else if tok.contains('=') {
                // next key=value field — stop if not ours
                break;
            }
        }
        if let Some(len) = len_bytes {
            return Some(PdiBlobFingerprint {
                len_bytes: len,
                sha256_prefix16: sha16,
                sha256_hex: String::new(),
            });
        }
    }
    // Split form: pdi_fp_len=N pdi_fp_sha16=HEX
    let mut len_bytes: Option<u64> = None;
    let mut sha16 = String::new();
    for tok in detail.split_whitespace() {
        if let Some(v) = tok.strip_prefix("pdi_fp_len=") {
            let v = v.trim_end_matches([',', ';']);
            len_bytes = v.parse().ok();
        } else if let Some(v) = tok.strip_prefix("pdi_fp_sha16=") {
            let v = v.trim_end_matches([',', ';']);
            if v != "absent" && !v.is_empty() {
                sha16 = v.to_ascii_lowercase();
            }
        }
    }
    len_bytes.map(|len| PdiBlobFingerprint {
        len_bytes: len,
        sha256_prefix16: sha16,
        sha256_hex: String::new(),
    })
}

impl ResearchPdiSourceKind {
    /// When CONFIG_CU present without size and no useful hint → unknown opaque.
    fn max_absent_to_unknown(self) -> Self {
        match self {
            Self::Absent => Self::UnknownOpaque,
            other => other,
        }
    }
}

/// Live C2 journal dual-status pair (research only; never invents product Pass).
///
/// Operator C2 (2026-07-18): `Failed cmd … 0x3000003` + nearby `Status 0x4000003`.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct JournalFwStatusPair {
    /// From `Failed cmd … status 0x…` when present.
    pub failed_cmd_status: Option<u32>,
    /// From a standalone `Status 0x…` line (completion-chain) when present.
    pub chain_status: Option<u32>,
}

impl JournalFwStatusPair {
    /// True when the locked live pair is present (APP_LOAD fail + INVALID_PARAM chain).
    #[must_use]
    pub fn is_c2_app_load_pair(&self) -> bool {
        self.failed_cmd_status == Some(AIE2_FW_APP_LOAD_PDI_FAIL)
            && self.chain_status == Some(AIE2_FW_INVALID_PARAM)
    }

    /// Soft report tokens (never claims Pass / C-ready).
    #[must_use]
    pub fn format_soft_note(&self) -> String {
        let mut parts = vec![
            "journal_fw_pair".into(),
            "not_c_ready=1".into(),
            "not_ran_on_npu=1".into(),
            "invent_pass=0".into(),
        ];
        match self.failed_cmd_status {
            Some(c) => {
                parts.push(format!("failed_cmd=0x{c:x}"));
                parts.push(format!("failed_cmd_name={}", aie2_fw_status_name(c)));
            }
            None => parts.push("failed_cmd=absent".into()),
        }
        match self.chain_status {
            Some(c) => {
                parts.push(format!("chain_status=0x{c:x}"));
                parts.push(format!("chain_name={}", aie2_fw_status_name(c)));
            }
            None => parts.push("chain_status=absent".into()),
        }
        if self.is_c2_app_load_pair() {
            parts.push("c2_app_load_pair=1".into());
        }
        parts.join(" ")
    }
}

/// Parse journal (or multi-line) text for Failed-cmd + Status hex codes.
///
/// **Never** invents codes: only literal `0x…` on lines that match the pure
/// token helpers ([`parse_failed_cmd_status_token`] /
/// [`parse_chain_status_token`]). First match wins per field.
#[must_use]
pub fn parse_journal_fw_status_pair(text: &str) -> JournalFwStatusPair {
    let mut out = JournalFwStatusPair::default();
    for line in text.lines() {
        if out.failed_cmd_status.is_none()
            && let Some(c) = parse_failed_cmd_status_token(line)
        {
            out.failed_cmd_status = Some(c);
        }
        if out.chain_status.is_none()
            && let Some(c) = parse_chain_status_token(line)
        {
            out.chain_status = Some(c);
        }
    }
    out
}

/// Pure single-line parser: Failed-cmd status hex when the line is a failed-cmd
/// journal line.
///
/// Accepts `failed cmd` / `failed_cmd` (case-insensitive). Returns the first
/// `0x…` token on that line only. **Never** invents codes from unrelated text.
///
/// Stamp `2c4b96bf` unit surface (with multi-line pair parse).
#[must_use]
pub fn parse_failed_cmd_status_token(line: &str) -> Option<u32> {
    let l = line.trim();
    if l.is_empty() {
        return None;
    }
    let ll = l.to_ascii_lowercase();
    if !(ll.contains("failed cmd") || ll.contains("failed_cmd")) {
        return None;
    }
    first_hex_status_token(l)
}

/// Pure single-line parser: chain/completion `Status 0x…` when the line is **not**
/// a Failed-cmd line.
///
/// Requires a `status 0x` / `status 0X` substring and excludes failed-cmd lines so
/// the primary load-reject code is not double-counted as chain status.
///
/// Stamp `2c4b96bf` unit surface (with multi-line pair parse).
#[must_use]
pub fn parse_chain_status_token(line: &str) -> Option<u32> {
    let l = line.trim();
    if l.is_empty() {
        return None;
    }
    let ll = l.to_ascii_lowercase();
    if ll.contains("failed cmd") || ll.contains("failed_cmd") {
        return None;
    }
    if !ll.contains("status 0x") {
        return None;
    }
    first_hex_status_token(l)
}

/// First `0x` / `0X` hex u32-ish token on a line (truncates to low 32 bits if longer).
///
/// Public pure helper for journal research; **never** invents a code without a
/// literal hex token. Prefer [`parse_failed_cmd_status_token`] /
/// [`parse_chain_status_token`] for typed line roles.
#[must_use]
pub fn first_hex_status_token(line: &str) -> Option<u32> {
    let bytes = line.as_bytes();
    let mut i = 0;
    while i + 2 < bytes.len() {
        if bytes[i] == b'0' && (bytes[i + 1] == b'x' || bytes[i + 1] == b'X') {
            let start = i + 2;
            let mut end = start;
            while end < bytes.len() && bytes[end].is_ascii_hexdigit() {
                end += 1;
            }
            if end > start {
                let hex = &line[start..end];
                // Accept up to 16 hex digits; use low 32 bits of the parse.
                if let Ok(v) = u64::from_str_radix(hex, 16) {
                    return u32::try_from(v & 0xffff_ffff).ok();
                }
            }
            i = end;
            continue;
        }
        i += 1;
    }
    None
}

/// Max hex words accepted from a fixture/list (research dumps are tiny).
pub const PARSE_U32_HEX_WORD_LIST_MAX: usize = 256;

/// Parse LE u32 word list from a research fixture (one hex word per line; `#` comments).
///
/// Refuses empty input and lists longer than [`PARSE_U32_HEX_WORD_LIST_MAX`].
///
/// # Errors
///
/// Invalid hex token, empty after strip, or too many words.
pub fn parse_u32_hex_word_list(text: &str) -> Result<Vec<u32>, String> {
    let mut out = Vec::new();
    for (lineno, raw) in text.lines().enumerate() {
        let line = raw.split('#').next().unwrap_or("").trim();
        if line.is_empty() {
            continue;
        }
        if out.len() >= PARSE_U32_HEX_WORD_LIST_MAX {
            return Err(format!(
                "too many hex words (max {PARSE_U32_HEX_WORD_LIST_MAX})"
            ));
        }
        let hex = line
            .strip_prefix("0x")
            .or_else(|| line.strip_prefix("0X"))
            .unwrap_or(line);
        let w = u32::from_str_radix(hex, 16)
            .map_err(|e| format!("line {}: bad hex {line:?}: {e}", lineno + 1))?;
        out.push(w);
    }
    if out.is_empty() {
        return Err("no hex words".into());
    }
    Ok(out)
}

/// Decode a pure START_NPU Cmd BO (header + payload) into fields.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StartNpuCmdDecode {
    /// Unpacked header state nibble.
    pub state: u32,
    /// Unpacked header count (data dwords).
    pub count: u32,
    /// Unpacked header opcode.
    pub opcode: u32,
    /// CU mask dword.
    pub cu_mask: u32,
    /// Instruction buffer device address.
    pub inst_addr: u64,
    /// START_NPU size field.
    pub inst_size: u32,
    /// Property count field (shim I/O uses 0).
    pub prop_count: u32,
    /// Flexible-array dwords after prop_count.
    pub flexible_args: Vec<u32>,
}

/// Decode START_NPU Cmd BO built by [`build_ert_start_npu_cmd_bo_ex`] family.
///
/// # Errors
///
/// Truncated buffer or count mismatch.
pub fn decode_start_npu_cmd_bo(bytes: &[u8]) -> Result<StartNpuCmdDecode, String> {
    use super::direct::{ErtCmdOpcode, parse_amdxdna_cmd_header_from_bytes};
    let h = parse_amdxdna_cmd_header_from_bytes(bytes).map_err(|e| e.to_string())?;
    if h.opcode != ErtCmdOpcode::StartNpu as u32 {
        return Err(format!("opcode {} not START_NPU", h.opcode));
    }
    let need = 4usize.saturating_add((h.count as usize).saturating_mul(4));
    if bytes.len() < need {
        return Err(format!(
            "cmd bo short: have {} need {need} (count={})",
            bytes.len(),
            h.count
        ));
    }
    if h.count < 5 {
        return Err(format!("count {} < 5 (cu+buf+size+prop)", h.count));
    }
    let mut dwords = Vec::with_capacity(h.count as usize);
    for i in 0..h.count as usize {
        let o = 4 + i * 4;
        dwords.push(u32::from_le_bytes([
            bytes[o],
            bytes[o + 1],
            bytes[o + 2],
            bytes[o + 3],
        ]));
    }
    let cu_mask = dwords[0];
    let inst_addr = u64::from(dwords[1]) | (u64::from(dwords[2]) << 32);
    let inst_size = dwords[3];
    let prop_count = dwords[4];
    let flexible_args = dwords[5..].to_vec();
    Ok(StartNpuCmdDecode {
        state: h.state,
        count: h.count,
        opcode: h.opcode,
        cu_mask,
        inst_addr,
        inst_size,
        prop_count,
        flexible_args,
    })
}

/// Rebuild pure START_NPU for C2 live paddrs (xrt3, content size 1688, prop_count=0).
///
/// Research helper — does **not** submit.
///
/// # Errors
///
/// Builder refuse (should not happen for valid paddrs).
pub fn rebuild_c2_live_start_npu_cmd_bo(
    inst_addr: u64,
    inst_size: u32,
    ifm: u64,
    wts: u64,
    ofm: u64,
    cu_mask: u32,
) -> Result<Vec<u8>, String> {
    let kargs =
        pack_start_npu_kernel_args_with_ctrl_layout(ifm, wts, ofm, None, LabKernelArgLayout::Xrt3);
    build_ert_start_npu_cmd_bo_with_kernel_args(inst_addr, inst_size, &kargs, cu_mask)
        .map_err(|e| e.to_string())
}

/// Word-level diff summary (research).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct U32WordDiff {
    /// Length of left slice.
    pub left_len: usize,
    /// Length of right slice.
    pub right_len: usize,
    /// First index where words differ (or min len if prefix-equal but lens differ).
    pub first_mismatch: Option<usize>,
    /// Count of differing positions in shared prefix.
    pub mismatch_count: usize,
}

/// Diff two u32 word lists.
#[must_use]
pub fn diff_u32_word_lists(left: &[u32], right: &[u32]) -> U32WordDiff {
    let n = left.len().min(right.len());
    let mut mismatch_count = 0usize;
    let mut first = None;
    for i in 0..n {
        if left[i] != right[i] {
            mismatch_count += 1;
            if first.is_none() {
                first = Some(i);
            }
        }
    }
    if first.is_none() && left.len() != right.len() {
        first = Some(n);
    }
    U32WordDiff {
        left_len: left.len(),
        right_len: right.len(),
        first_mismatch: first,
        mismatch_count,
    }
}

